import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import pdf from 'pdf-parse';
import natural from 'natural';

export const analyzeResume = async (fileBuffer: Buffer, targetKeywords: string[]) => {
  const data = await pdf(fileBuffer);
  const text = data.text.toLowerCase();
  const tokenizer = new natural.WordTokenizer();
  const tokens = tokenizer.tokenize(text);

  const breakdown = targetKeywords.map(keyword => {
    const count = tokens.filter(t => t === keyword.toLowerCase()).length;
    return { keyword, count, found: count > 0 };
  });

  const score = (breakdown.filter(i => i.found).length / targetKeywords.length) * 100;
  return { score, breakdown };
};

import { create } from 'zustand';

interface ScanStore {
  score: number;
  breakdown: { keyword: string; count: number; found: boolean }[];
  isLoading: boolean;
  setResults: (score: number, breakdown: any[]) => void;
  setLoading: (val: boolean) => void;
}

export const useScanStore = create<ScanStore>((set) => ({
  score: 0,
  breakdown: [],
  isLoading: false,
  setResults: (score, breakdown) => set({ score, breakdown, isLoading: false }),
  setLoading: (isLoading) => set({ isLoading }),
}));
